"""Generate focused permission-guide teaching diagrams and an independent registry.

Run from an isolated or integrated scripts directory. Only these twelve SVGs,
the named registry and frame metadata are written below that script's root.
"""
from pathlib import Path
from html import escape
import csv,json,re,unicodedata,base64
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/public/images/guides';ART=ROOT/'artifacts'
INK='#24384f';MUTED='#536b83';BLUE='#267cba';PURPLE='#7154d9';GREEN='#258568'
ICON_DATA=''
SOURCES='f02f50e: permissionguidewidget.cpp:22-27,84-116,182-244; permissionguidecontroller.cpp:69-76,94-161,163-217; apppermissionservice.cpp:194-238; macos/apppermissionbackend.mm:14-96; settingspagewidget.cpp:681-704,1101-1135'

def L(a,b):return {'zh':a,'en':b}
def pick(v,l):return v[l] if isinstance(v,dict) else str(v)
def measure(s):return sum(1 if unicodedata.east_asian_width(c) in 'WF' else .55 for c in s)
def wrap(s,width=346,size=20):
 lines=[];line='';gap=''
 for token in re.findall(r'\s+|[^\s\u3400-\u9fff]+|[\u3400-\u9fff]',s):
  if token.isspace():gap=' ' if line else '';continue
  if line and measure(line+gap+token)*size>width and token not in '，。；：！？、）】》':lines.append(line);line='';gap=''
  line+=gap+token;gap=''
 if line:lines.append(line)
 return lines

def txt(x,y,s,size=20,color=INK,weight=400):return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" font-weight="{weight}">{escape(s)}</text>'
def block(x,y,s,width=346,size=20,color=INK):
 lines=wrap(s,width,size);return ''.join(txt(x,y+i*(size+7),v,size,color) for i,v in enumerate(lines)),len(lines)*(size+7)
def rect(x,y,w,h,fill='white',stroke='#c8d3e6',radius=10,extra=''):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{radius}" fill="{fill}" stroke="{stroke}" stroke-width="1.4" {extra}/>'
def button(x,y,text,w=170,disabled=False,success=False):
 color=MUTED if disabled else GREEN if success else BLUE;fill='#e3e8f0' if disabled else '#e9f6f0' if success else '#eaf3ff'
 return rect(x,y,w,42,fill,color,7)+txt(x+12,y+28,text,19,color)
def arrow(y):return f'<path d="M220 {y}v24m-7-7 7 7 7-7" fill="none" stroke="{BLUE}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>'
def card(y,h,title,body=None,l='zh'):
 s=rect(24,y,392,h)+txt(40,y+29,pick(title,l),21,PURPLE)
 if body:
  q,_=block(40,y+62,pick(body,l));s+=q
 return s

def app_status(y,l,permission,status='settings'):
 title=L('应用权限','App permissions');name=pick(permission,l)
 body=rect(24,y,392,151)+txt(40,y+30,pick(title,l),21,PURPLE)
 b,lines=block(40,y+61,name,width=350,size=20);body+=b
 label=pick(L('已授权','Authorized') if status=='authorized' else L('前往设置','Go to settings'),l)
 body+=button(232,y+97,label,168,success=status=='authorized')
 return body

def guide(y,l,mode='drag',pending=False,compact=False):
 if compact:
  s=card(y,194,L('引导中的应用行','Helper application row'),l=l);rowy=y+71
 else:
  s=rect(24,y,392,250,'#fff','#bac8d9')+txt(39,y+29,'↑',25,BLUE)+txt(385,y+29,'×',24,MUTED)
  message=L('将“Snow Shot”拖到上方的权限列表中；若已在列表中，请开启权限','Drag ‘Snow Shot’ into the permissions list above. If it is already listed, turn it on') if mode=='drag' else L('请求麦克风权限，然后在 macOS 提示中选择允许','Request microphone access, then allow it in the macOS prompt')
  b,height=block(75,y+30,pick(message,l),width=298,size=20);s+=b;rowy=y+30+height+12
 if mode=='drag':
  s+=rect(40,rowy,352,58,'#f0f4f8','#d1dbe9',6)
  s+=f'<image x="49" y="{rowy+7}" width="44" height="44" href="data:image/png;base64,{ICON_DATA}"/>'
  s+=txt(105,rowy+36,'Snow Shot',22)
 else:
  s+=button(202,rowy,pick(L('正在请求…','Requesting…') if pending else L('请求权限','Request access'),l),190,disabled=pending)
 return s

FRAMES=[
 {'family':'start-permission-drag','label':L('先进入对应权限页','Open the permission settings'),'caption':L('在应用权限中点击前往设置。系统设置在前台时，查看随窗口出现的引导和 Snow Shot 应用行。','Click Go to settings in App permissions. With System Settings in front, locate the helper and its Snow Shot application row.'),'ids':'START-035;START-036;START-038;START-046','section':L('拖入应用并打开系统开关','drag-the-app-and-enable-access')},
 {'family':'start-permission-drag','label':L('拖入后检查列表','Drag, then check the list'),'caption':L('权限列表没有当前副本时，拖动引导中的应用行到列表并松开。检查 Snow Shot 是否出现；已有条目时无需重复添加。','If the current copy is absent, drag the helper’s application row into the permission list and release. Check that Snow Shot appears; do not add another entry if it is already listed.'),'ids':'START-046','section':L('拖入应用并打开系统开关','drag-the-app-and-enable-access')},
 {'family':'start-permission-drag','label':L('打开系统开关再验证','Enable access, then verify'),'caption':L('在系统列表开启当前 Snow Shot 的权限；按系统要求重启。回应用检查已授权，再实际完成一次截图或对应动作。拖入本身不会完成授权。','Turn on access for the current Snow Shot in the system list and restart if requested. Recheck Authorized in the app, then perform a capture or the relevant action. Dragging alone does not grant access.'),'ids':'START-035;START-037;START-038;START-046','section':L('拖入应用并打开系统开关','drag-the-app-and-enable-access')},
 {'family':'start-permission-microphone','label':L('首次请求麦克风','Request microphone access'),'caption':L('尚未请求过麦克风时，从前往设置打开的引导中点击请求权限。麦克风不使用拖入应用行。','If microphone access has not been requested, use Request access in the helper opened from Go to settings. The microphone flow does not use an application drag row.'),'ids':'START-036;START-041;START-047','section':L('第一次请求麦克风权限','request-microphone-access-for-the-first-time')},
 {'family':'start-permission-microphone','label':L('等待系统返回结果','Wait for the system result'),'caption':L('正在请求…期间按钮不可重复点击。在 macOS 的麦克风请求中允许访问，然后等待结果；请求结束不等于已经授权。','Requesting… is disabled against repeat clicks. Allow access in the macOS microphone prompt and wait for the result; the request ending does not itself mean access was authorized.'),'ids':'START-041;START-047','section':L('第一次请求麦克风权限','request-microphone-access-for-the-first-time')},
 {'family':'start-permission-microphone','label':L('已授权后测试声音','Check Authorized and test audio'),'caption':L('系统确认允许后，权限引导自动收起。回应用检查麦克风为已授权，再录一段启用麦克风的 MP4，停止后回放检查声音。','After the system grants access, the helper closes automatically. Recheck Authorized for Microphone, then record an MP4 with the microphone enabled, stop it and play it to check audio.'),'ids':'START-035;START-037;START-041;START-047','section':L('第一次请求麦克风权限','request-microphone-access-for-the-first-time')}
]

def render(index,l):
 f=FRAMES[index];title=escape(pick(f["label"],l));s=f'<svg xmlns="http://www.w3.org/2000/svg" width="440" height="650" viewBox="0 0 440 650"><title>{title}</title><rect width="440" height="650" rx="14" fill="#f5f7fc"/><g font-family="Arial, PingFang SC, Microsoft YaHei, sans-serif">'
 b,_=block(24,32,pick(f['label'],l),width=392,size=23);s+=b
 if index==0:
  s+=app_status(78,l,L('屏幕与系统音频录制','Screen & System Audio Recording'))+arrow(237)+guide(278,l)
  s+=card(548,57,L('先找应用行，再拖动','Locate the application row'),l=l)
 elif index==1:
  s+=rect(24,78,392,123,'#fff','#7e9dba',10,'stroke-dasharray="6 5"')+txt(40,111,pick(L('系统设置：权限列表','System Settings: permission list'),l),20,PURPLE)
  b,_=block(40,146,pick(L('松开后检查 Snow Shot 是否出现。','After releasing, check for Snow Shot.'),l));s+=b
  s+=f'<path d="M220 246v-24m-7 7 7-7 7 7" fill="none" stroke="{BLUE}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>'
  s+=guide(266,l,compact=True)
  s+=card(480,125,L('如果已经在列表中','If it is already listed'),L('不用再次拖入；找到当前副本，继续打开系统开关。','Do not drag it in again. Find the current copy and turn on its access.'),l)
 elif index==2:
  s+=card(78,150,L('在系统设置中操作','Act in System Settings'),L('找到当前 Snow Shot，打开权限开关。若系统要求重新打开应用，按提示完成。','Find the current Snow Shot and turn on access. Reopen the app if the system asks.'),l)+arrow(237)
  s+=app_status(278,l,L('屏幕与系统音频录制','Screen & System Audio Recording'),'authorized')
  s+=card(449,156,L('还要检查实际结果','Check the actual result too'),L('回到应用，执行一次相关动作；例如截图后检查画面。拖入应用不等于已授权。','Perform the action in Snow Shot and check the result. Dragging alone does not authorize the app.'),l)
 elif index==3:
  s+=app_status(78,l,L('麦克风','Microphone'))+arrow(237)+guide(278,l,mode='microphone')
  s+=card(548,57,L('麦克风使用请求按钮','Use Request access'),l=l)
 elif index==4:
  s+=guide(78,l,mode='microphone',pending=True)
  s+=card(350,151,L('在 macOS 提示中允许','Allow access in the macOS prompt'),L('允许麦克风访问，然后等待系统返回结果。','Allow microphone access, then wait for the system result.'),l)
  s+=card(521,84,L('请求结束不等于已授权','Request finished ≠ Authorized'),l=l)
 else:
  s+=app_status(78,l,L('麦克风','Microphone'),'authorized')
  s+=card(251,120,L('权限引导自动收起','The helper closes automatically'),L('以应用内已授权状态为准。','Check the Authorized status in the app.'),l)
  s+=card(392,213,L('再录短片检查声音','Record a short audio check'),L('选择 MP4，启用麦克风。开始 → 说一句话 → 停止 → 回放，确认能听到自己的声音。','Choose MP4 and enable the microphone. Start → speak → stop → play the file and check that your voice is audible.'),l)
 s+=f'<path d="M24 620H416" stroke="#dbe3ef"/>'+txt(24,640,pick(L('操作示意','Instructional illustration'),l),17,MUTED)+'</g></svg>\n'
 return s

def main():
 OUT.mkdir(parents=True,exist_ok=True);ART.mkdir(parents=True,exist_ok=True);rows=[];players=[]
 for l in ['zh','en']:
  for family in ['start-permission-drag','start-permission-microphone']:
   frames=[];n=0
   for i,f in enumerate(FRAMES):
    if f['family']!=family:continue
    n+=1;folder=OUT/('en' if l=='en' else '');folder.mkdir(exist_ok=True);p=folder/f'{family}-{n}.svg';p.write_text(render(i,l))
    asset=str(p.relative_to(ROOT));page=f'docs/{l}/guides/getting-started/permissions.mdx';section=pick(f['section'],l);src='/'+asset.removeprefix('docs/public/')
    frames.append({'src':src,'alt':pick(f['caption'],l),'label':pick(f['label'],l),'caption':pick(f['caption'],l)})
    rows.append({'Asset':asset,'Feature IDs':f['ids'],'Teaching purpose':pick(f['label'],l),'Documentation path':page+'#'+section,'Associated step':str(n),'Source':SOURCES,'Production method':'Source-backed focused SVG illustration; existing public app-icon.webp losslessly decoded to embedded PNG; conceptual system action/list only, no fabricated macOS prompt or native UI claim.','Status':'已制作：操作示意；普通系统拖入/授权尚未实测','Capture prerequisites and next action':'For ordinary UI verification use the intended application copy, inspect the system permission list, enable access, recheck app status and complete the relevant task. A drag or pending-request state is not authorization proof.'})
   players.append({'locale':l,'family':family,'frames':frames})
 with (ART/'assets-permission-state-20261110c.csv').open('w',newline='') as out:
  writer=csv.DictWriter(out,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)
 (ART/'permission-state-frames-20261110c.json').write_text(json.dumps({'players':players,'dimensions':[440,650]},ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'SVG':len(rows),'locale_pairs':6,'dimensions':[440,650]}))
if __name__=='__main__':main()
